   151→template <class T,class TLink>
   152→void RemoveFromLink(T *ap)
   153→{
   154→	TLink *lst = ap->pLink;
   155→	if(!lst) return ;
   156→	assert( lst->head && lst->tail );
   157→
   158→	if( ap == lst->head )
   159→	{
   160→		lst->head = ap->pNext;
   161→		if(lst->head)
   162→		{
   163→			lst->head->pPrev = NULL;
   164→		}
   165→	}
   166→	else
   167→	{
   168→		if(ap->pPrev)
   169→		{
   170→			ap->pPrev->pNext = ap->pNext;
   171→		}
   172→	}
   173→
   174→	if( ap == lst->tail )
   175→	{
   176→		lst->tail = ap->pPrev;
   177→		if(lst->tail)
   178→		{
   179→			lst->tail->pNext = NULL;
   180→		}
   181→	}
   182→	else
   183→	{
   184→		ap->pNext->pPrev = ap->pPrev;
   185→	}
   186→
   187→	ap->pPrev = ap->pNext = NULL;
   188→	ap->pLink = NULL;
   189→}
   190→
   191→template <class TNode,class TLink>
   192→void inline AddTail(TLink*apLink,TNode *ap)
   193→{
   194→	if( ap->pLink )
   195→	{
   196→		return ;
   197→	}
   198→	if(apLink->tail)
   199→	{
   200→		apLink->tail->pNext = (TNode*)ap;
   201→		ap->pNext = NULL;
   202→		ap->pPrev = apLink->tail;
   203→		apLink->tail = ap;
   204→	}
   205→	else
   206→	{
   207→		apLink->head = apLink->tail = ap;
   208→		ap->pNext = ap->pPrev = NULL;
   209→	}
   210→	ap->pLink = apLink;
   211→}
   212→template <class TNode,class TLink>
   213→void inline PopHead( TLink*apLink )
   214→{
   215→	if( !apLink->head ) 
   216→	{
   217→		return ;
   218→	}
   219→	TNode *lp = apLink->head;
   220→	if( apLink->head == apLink->tail )
   221→	{
   222→		apLink->head = apLink->tail = NULL;
   223→	}
   224→	else
   225→	{
   226→		apLink->head = apLink->head->pNext;
   227→	}
   228→
   229→	lp->pPrev = lp->pNext = NULL;
   230→	lp->pLink = NULL;
   231→
   232→	if( apLink->head )
   233→	{
   234→		apLink->head->pPrev = NULL;
   235→	}
   236→}
   237→
   238→template <class TNode,class TLink>
   239→void inline Join( TLink*apLink,TLink *apOther )
   240→{
   241→	//printf("apOther %p\n",apOther);
   242→	if( !apOther->head )
   243→	{
   244→		return ;
   245→	}
   246→	TNode *lp = apOther->head;
   247→	while( lp )
   248→	{
   249→		lp->pLink = apLink;
   250→		lp = lp->pNext;
   251→	}
   252→	lp = apOther->head;
   253→	if(apLink->tail)
   254→	{
   255→		apLink->tail->pNext = (TNode*)lp;
   256→		lp->pPrev = apLink->tail;
   257→		apLink->tail = apOther->tail;
   258→	}
   259→	else
   260→	{
   261→		apLink->head = apOther->head;
   262→		apLink->tail = apOther->tail;
   263→	}
   264→
   265→	apOther->head = apOther->tail = NULL;
   266→}
