   574→// walkerdu 2018-01-14                                                                              
   575→// 用于reset超时无法重复使用的协程                                                                  
   576→void co_reset(stCoRoutine_t * co)
   577→{
   578→    if(!co->cStart || co->cIsMain)
   579→        return;
   580→
   581→    co->cStart = 0;
   582→    co->cEnd = 0;
   583→
   584→    // 如果当前协程有共享栈被切出的buff，要进行释放
   585→    if(co->save_buffer)
   586→    {
   587→        free(co->save_buffer);
   588→        co->save_buffer = NULL;
