   772→void OnPollPreparePfn( stTimeoutItem_t * ap,struct epoll_event &e,stTimeoutItemLink_t *active )
   773→{
   774→	stPollItem_t *lp = (stPollItem_t *)ap;
   775→	lp->pSelf->revents = EpollEvent2Poll( e.events );
   776→
   777→
